using System;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.Rendering;
public static class LionfishComparisonScene {
 const string Folder="Assets/UnderwaterArt/LionfishComparison/",Scene="Assets/Scenes/Lionfish_Comparison.unity";
 [MenuItem("Underwater/Open lionfish original vs reduced")]
 public static void Open(){if(EditorSceneManager.SaveCurrentModifiedScenesIfUserWantsTo())EditorSceneManager.OpenScene(Scene);}
 public static void Create(){
  AssetDatabase.Refresh();var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);
  foreach(var file in new[]{"Albedo.png","Normal.png","ORM.png"}){var ti=(TextureImporter)AssetImporter.GetAtPath(Folder+file);ti.maxTextureSize=4096;ti.mipmapEnabled=true;ti.textureCompression=TextureImporterCompression.Uncompressed;if(file=="Normal.png")ti.textureType=TextureImporterType.NormalMap;ti.SaveAndReimport();}
  var material=new Material(Shader.Find("Standard")){name="Original shared lionfish skin"};material.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(Folder+"Albedo.png");material.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>(Folder+"Normal.png"));material.EnableKeyword("_NORMALMAP");material.SetFloat("_Glossiness",.22f);material.SetFloat("_Metallic",0);var existing=AssetDatabase.LoadAssetAtPath<Material>(Folder+"SharedSkin.mat");if(existing){EditorUtility.CopySerialized(material,existing);UnityEngine.Object.DestroyImmediate(material);material=existing;EditorUtility.SetDirty(existing);}else AssetDatabase.CreateAsset(material,Folder+"SharedSkin.mat");
  var camera=new GameObject("Comparison Camera").AddComponent<Camera>();camera.tag="MainCamera";camera.transform.position=new Vector3(1.7f,.05f,0);camera.transform.LookAt(Vector3.zero);camera.orthographic=true;camera.orthographicSize=.40f;camera.aspect=1.8f;camera.nearClipPlane=.01f;camera.farClipPlane=10;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.08f,.105f,.13f);
  RenderSettings.fog=false;RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=new Color(.65f,.65f,.65f);var light=new GameObject("Shared soft key").AddComponent<Light>();light.type=LightType.Directional;light.intensity=1.1f;light.transform.rotation=Quaternion.Euler(35,-70,0);
  int[] expected={469558,19999};int i=0;
  foreach(var file in new[]{"Original.fbx","Reduced.fbx"}){
   string path=Folder+file;var importer=(ModelImporter)AssetImporter.GetAtPath(path);importer.animationType=ModelImporterAnimationType.Legacy;importer.importAnimation=true;importer.importCameras=false;importer.importLights=false;importer.materialImportMode=ModelImporterMaterialImportMode.None;importer.meshCompression=ModelImporterMeshCompression.Off;importer.isReadable=true;var specs=importer.defaultClipAnimations;foreach(var s in specs){s.name="GentleSwim";s.loopTime=true;s.wrapMode=WrapMode.Loop;}importer.clipAnimations=specs;importer.SaveAndReimport();
   var model=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(path));model.name=i==0?"Original lionfish | 469558 triangles":"Reduced lionfish | 19999 triangles";var renderers=model.GetComponentsInChildren<SkinnedMeshRenderer>();int triangles=renderers.Sum(r=>r.sharedMesh.triangles.Length/3);if(triangles!=expected[i])throw new Exception("Unexpected triangle count "+triangles);
   foreach(var r in renderers){r.sharedMaterial=material;r.updateWhenOffscreen=true;r.shadowCastingMode=ShadowCastingMode.Off;var b=r.localBounds;b.Expand(.08f);r.localBounds=b;}
   model.transform.rotation=Quaternion.Euler(0,180,0);var bounds=renderers[0].bounds;foreach(var r in renderers)bounds.Encapsulate(r.bounds);model.transform.position+=new Vector3(0,0,i==0?-.27f:.27f)-bounds.center;
   var player=model.GetComponent<Animation>();if(!player)player=model.AddComponent<Animation>();var clip=AssetDatabase.LoadAllAssetsAtPath(path).OfType<AnimationClip>().First(c=>!c.name.StartsWith("__"));player.AddClip(clip,"GentleSwim");player.clip=clip;player.playAutomatically=true;player.wrapMode=WrapMode.Loop;player.cullingType=AnimationCullingType.AlwaysAnimate;model.AddComponent<LionfishComparisonPlayback>().clip=clip;
   Label(i==0?"ORIGINAL\n469,558 triangles":"REDUCED\n19,999 triangles",new Vector3(0,.215f,i==0?-.27f:.27f),camera,.0028f);
   i++;
  }
  Label("Same textures / same swim cycle  |  95.7% fewer triangles",new Vector3(0,-.23f,0),camera,.0018f);
  var views=camera.gameObject.AddComponent<LionfishComparisonViews>();views.fish=UnityEngine.Object.FindObjectsByType<LionfishComparisonPlayback>(FindObjectsSortMode.None).Select(p=>p.transform).ToArray();AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(scene,Scene);Validate();Capture();CaptureFront();Debug.Log("LIONFISH_COMPARISON_CREATED "+Scene);
 }
 static void Label(string text,Vector3 position,Camera cam,float size){var go=new GameObject(text.Split('\n')[0]);go.transform.position=position;go.transform.rotation=cam.transform.rotation;var t=go.AddComponent<TextMesh>();t.text=text;t.fontSize=64;t.characterSize=size;t.anchor=TextAnchor.MiddleCenter;t.alignment=TextAlignment.Center;t.color=new Color(.88f,.94f,1);}
 public static void Validate(){EditorSceneManager.OpenScene(Scene);var players=UnityEngine.Object.FindObjectsByType<Animation>(FindObjectsSortMode.None);if(players.Length!=2)throw new Exception("Comparison must have two fish");var report=new System.Text.StringBuilder();foreach(var player in players){var skin=player.GetComponentInChildren<SkinnedMeshRenderer>();var before=new Mesh();var after=new Mesh();player.clip.SampleAnimation(player.gameObject,0);skin.BakeMesh(before);player.clip.SampleAnimation(player.gameObject,.75f);skin.BakeMesh(after);float moved=0;var a=before.vertices;var b=after.vertices;for(int n=0;n<a.Length;n++)moved=Mathf.Max(moved,(a[n]-b[n]).magnitude);var gill=skin.bones.First(t=>t.name=="GillLeft");player.clip.SampleAnimation(player.gameObject,0);var closed=gill.localRotation;player.clip.SampleAnimation(player.gameObject,.5f);if(Quaternion.Angle(closed,gill.localRotation)<.5f)throw new Exception("Gill breathing frozen");if(moved<.0001f)throw new Exception("Fish animation frozen");if(skin.bones.Length!=9||!skin.sharedMaterial.mainTexture)throw new Exception("Rig/material import invalid");report.AppendLine(player.name+" triangles="+skin.sharedMesh.triangles.Length/3+" bones="+skin.bones.Length+" sampled motion="+moved);UnityEngine.Object.DestroyImmediate(before);UnityEngine.Object.DestroyImmediate(after);player.clip.SampleAnimation(player.gameObject,0);}Directory.CreateDirectory("Renders/LionfishComparison");File.WriteAllText("Renders/LionfishComparison/Validation.txt",report.ToString());Debug.Log("LIONFISH_COMPARISON_VALIDATED");}
 public static void CaptureFront(){EditorSceneManager.OpenScene(Scene);var models=UnityEngine.Object.FindObjectsByType<LionfishComparisonPlayback>(FindObjectsSortMode.None);foreach(var p in models){var r=p.GetComponentInChildren<SkinnedMeshRenderer>();p.transform.RotateAround(r.bounds.center,Vector3.up,90);}foreach(float time in new[]{0f,.25f,.5f,.75f}){foreach(var p in models)p.clip.SampleAnimation(p.gameObject,time);Underwater.Editor.ReefCorrectionAudit.Capture(Camera.main,"Renders/LionfishComparison/Front"+time.ToString("0.00",System.Globalization.CultureInfo.InvariantCulture)+".png");}} public static void Capture(){EditorSceneManager.OpenScene(Scene);var camera=Camera.main;foreach(float time in new[]{0f,.75f,1.5f,2.25f}){foreach(var a in UnityEngine.Object.FindObjectsByType<Animation>(FindObjectsSortMode.None))a.clip.SampleAnimation(a.gameObject,time);Underwater.Editor.ReefCorrectionAudit.Capture(camera,"Renders/LionfishComparison/Phase"+time.ToString("0.00",System.Globalization.CultureInfo.InvariantCulture)+".png");}}
}
